    public static int[][] getCollisionGrid(int roomX, int roomY) {
        if (roomX < 0 || roomX >= 16 || roomY < 0 || roomY >= 8) return null;
        String data = GRIDS[roomY][roomX];
        if (data == null || data.length() != 176) return null;

        int tilesX = ZeldaRoom.TILES_X;
        int tilesY = ZeldaRoom.TILES_Y;
        int[][] grid = new int[tilesX][tilesY];
        for (int ty = 0; ty < tilesY; ty++) {
            for (int tx = 0; tx < tilesX; tx++) {
                grid[tx][ty] = data.charAt(ty * tilesX + tx) - '0';
            }
        }
        return grid;
    }

    /**
     * Find the CAVE tile position in a room's collision grid.
     * Returns [tileX, tileY] or null if no CAVE tile exists.
     */
    public static int[] findCaveEntrance(int roomX, int roomY) {
        if (roomX < 0 || roomX >= 16 || roomY < 0 || roomY >= 8) return null;
        String data = GRIDS[roomY][roomX];
        if (data == null) return null;
        int tilesX = ZeldaRoom.TILES_X;
        for (int i = 0; i < data.length(); i++) {
            if (data.charAt(i) == '5') { // CAVE tile
                int tx = i % tilesX;
                int ty = i / tilesX;
                return new int[]{tx, ty};
            }
        }
        return null;
    }
